ids = ["LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
assert set(P.keys()) == set(ids), (set(ids) ^ set(P.keys()))
written = []
for cid in ids:
    obj = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    fp = OUT / f"{cid}.json"
    fp.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    back = json.loads(fp.read_text(encoding="utf-8"))
    assert back["case_id"] == cid and set(back.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(back["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    assert 0 <= back["confidence"] <= 1
    written.append((cid, fp.stat().st_size))
for cid, sz in written:
    print(cid, sz)
print("TOTAL", len(written))
cm = sum(1 for c in ids if P[c]["trigger"]["changed_main"])
